package com.eventdrivencommerce.payment.infrastructure.provider;
import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.util.UUID;import static org.assertj.core.api.Assertions.*;
class SimulatedPaymentProviderTest{@Test void returnsStableReferenceForSameIdempotencyKey(){var provider=new SimulatedPaymentProvider("SUCCESS");var id=UUID.randomUUID();var first=provider.capture(id,BigDecimal.TEN,"SEK","capture:"+id);var second=provider.capture(id,BigDecimal.TEN,"SEK","capture:"+id);assertThat(first.providerReference()).isEqualTo(second.providerReference());}@Test void declineIsPermanentBusinessOutcome(){var result=new SimulatedPaymentProvider("DECLINE").capture(UUID.randomUUID(),BigDecimal.TEN,"SEK","key");assertThat(result.successful()).isFalse();assertThat(result.reasonCode()).isEqualTo("SIMULATED_DECLINE");assertThat(result.retryable()).isFalse();}@Test void timeoutIsTechnicalFailure(){var provider=new SimulatedPaymentProvider("TIMEOUT");assertThatThrownBy(()->provider.capture(UUID.randomUUID(),BigDecimal.TEN,"SEK","key")).isInstanceOf(ProviderTimeoutException.class);}}
